  ('quant', 'profit-loss', 'An article bought for ₹800 is sold for ₹920. Find the profit percentage.', '15%', '18%', '20%', '12%', 'A', 'Profit = 120; 120/800 × 100 = 15%.', 'Profit percentage', 'easy', '{}'),
  ('quant', 'discount', 'The marked price is ₹1,500. Successive discounts of 10% and 20% are given. Find the selling price.', '₹1,050', '₹1,080', '₹1,200', '₹1,100', 'B', '1500 × 0.9 × 0.8 = ₹1,080.', 'Successive discounts', 'moderate', '{}'),
