  ('quant', 'compound-interest', 'Find the compound interest on ₹10,000 at 10% per annum for 2 years, compounded annually.', '₹2,010', '₹2,000', '₹2,200', '₹2,100', 'D', 'Amount = 10000 × 1.1² = 12,100; CI = ₹2,100.', 'Compound interest', 'moderate', '{}'),
  ('quant', 'ratio-proportion', '₹1,200 is divided in the ratio 3 : 5. Find the larger share.', '₹750', '₹450', '₹800', '₹700', 'A', 'Larger share = 5/8 × 1200 = ₹750.', 'Ratio division', 'easy', '{}'),
  ('quant', 'average', 'The average of 5 numbers is 42. When one number is removed, the average of the rest is 40. Find the number removed.', '48', '50', '46', '52', 'B', 'Total 5 × 42 = 210; remaining 4 × 40 = 160; removed = 50.', 'Average', 'moderate', '{}'),
  ('quant', 'time-work', 'A can finish a job in 12 days and B in 18 days. Working together, how long will they take?', '8 days', '7.5 days', '7.2 days', '6 days', 'C', '1/12 + 1/18 = 5/36 per day, so 36/5 = 7.2 days.', 'Combined work', 'moderate', '{}'),
  ('quant', 'pipes-cisterns', 'A pipe fills a tank in 6 hours and another empties it in 9 hours. If both are opened together, the tank fills in:', '15 hours', '3 hours', '12 hours', '18 hours', 'D', 'Net rate = 1/6 − 1/9 = 1/18, so 18 hours.', 'Pipes and cisterns', 'moderate', '{}'),
