  ('quant', 'number-system', 'Find the LCM of 12, 18 and 30.', '90', '360', '120', '180', 'D', '12 = 2²·3, 18 = 2·3², 30 = 2·3·5; LCM = 2²·3²·5 = 180.', 'LCM', 'easy', '{}'),
