  ('ga-aviation', 'icao', 'The headquarters of the International Civil Aviation Organization (ICAO) is in:', 'Paris', 'Geneva', 'Montreal', 'New York', 'C', 'ICAO, a UN specialised agency, is headquartered in Montreal, Canada.', 'ICAO', 'easy', '{}'),
  ('ga-aviation', 'icao', 'ICAO was established under which convention?', 'Warsaw Convention', 'Tokyo Convention', 'Montreal Convention (1999)', 'Chicago Convention (1944)', 'D', 'The Convention on International Civil Aviation was signed in Chicago on 7 December 1944 and created ICAO.', 'Chicago Convention', 'moderate', '{}'),
  ('ga-aviation', 'icao', 'Which ICAO Annex deals with Aerodromes?', 'Annex 14', 'Annex 9', 'Annex 17', 'Annex 19', 'A', 'Annex 14 = Aerodromes. Annex 9 = Facilitation, Annex 17 = Security, Annex 19 = Safety Management.', 'ICAO Annexes', 'exam', '{}'),
  ('ga-aviation', 'iata', 'The International Air Transport Association (IATA) is an association of:', 'Airport operators', 'Airlines', 'Aircraft manufacturers', 'National aviation regulators', 'B', 'IATA is the trade association of the world''s airlines. Regulators work through ICAO; airports through ACI.', 'IATA', 'moderate', '{}'),
  ('ga-aviation', 'dgca', 'Which body is the regulator of civil aviation (safety, licensing, airworthiness) in India?', 'AAI', 'AERA', 'DGCA', 'BCAS', 'C', 'The Directorate General of Civil Aviation (DGCA) handles safety regulation, licensing and airworthiness.', 'DGCA', 'easy', '{}'),
  ('ga-aviation', 'bcas', 'Which organisation is the regulatory authority for civil aviation security in India?', 'CISF', 'DGCA', 'AAI', 'BCAS', 'D', 'The Bureau of Civil Aviation Security (BCAS) sets security standards. CISF provides security at many airports.', 'BCAS', 'easy', '{}'),
  ('ga-aviation', 'aai', 'The Airports Authority of India (AAI) was constituted in:', '1995', '2000', '1986', '1972', 'A', 'AAI was formed on 1 April 1995 under the AAI Act 1994 by merging the International Airports Authority of India and the National Airports Authority.', 'AAI', 'moderate', '{}'),
  ('ga-aviation', 'aera', 'The Airports Economic Regulatory Authority (AERA) mainly regulates:', 'Air traffic control procedures', 'Tariffs for aeronautical services at major airports', 'Aircraft airworthiness', 'Airport security', 'B', 'AERA (set up under the AERA Act 2008) determines tariffs for aeronautical services at major airports.', 'AERA', 'exam', '{}'),
  ('ga-aviation', 'airport-codes', 'What is the IATA code of Chennai International Airport?', 'CHE', 'CNN', 'MAA', 'MDS', 'C', 'Chennai''s IATA code is MAA, from its old name Madras.', 'IATA airport codes', 'easy', '{}'),
  ('ga-aviation', 'airport-codes', 'Which IATA code belongs to Kochi (Cochin) International Airport?', 'CCU', 'CCJ', 'KOC', 'COK', 'D', 'COK is Kochi. CCJ is Kozhikode (Calicut) and CCU is Kolkata.', 'IATA airport codes', 'moderate', '{}'),
  ('ga-aviation', 'airport-codes', 'ICAO location indicators for airports in India begin with the letter:', 'V', 'A', 'I', 'H', 'A', 'Indian ICAO codes start with V (e.g. VIDP Delhi, VABB Mumbai, VOMM Chennai, VECC Kolkata).', 'ICAO location indicators', 'exam', '{}'),
  ('ga-aviation', 'major-indian-airports', 'Netaji Subhas Chandra Bose International Airport is located in:', 'Guwahati', 'Kolkata', 'Bhubaneswar', 'Patna', 'B', 'Kolkata''s airport (IATA: CCU) is named after Netaji Subhas Chandra Bose.', 'Indian airports', 'easy', '{}'),
  ('ga-aviation', 'airports-india', 'Which Indian airport is widely known as the world''s first fully solar-powered airport?', 'Hyderabad', 'Bengaluru', 'Kochi', 'Ahmedabad', 'C', 'Cochin International Airport (CIAL) became fully solar-powered in 2015.', 'Indian airports', 'moderate', '{}'),
  ('ga-aviation', 'civil-aviation-policies', 'The UDAN scheme of the Government of India is associated with:', 'Pilot training', 'Airport privatisation', 'Aircraft manufacturing', 'Regional air connectivity', 'D', 'UDAN (Ude Desh ka Aam Nagrik) is the Regional Connectivity Scheme under the National Civil Aviation Policy 2016.', 'UDAN', 'easy', '{}'),
  ('ga-aviation', 'runways', 'A runway designated ''09'' at one end will be designated ___ at the opposite end.', '27', '90', '18', '36', 'A', 'Runway numbers are the magnetic heading ÷ 10. 090° reversed is 270°, so the other end is 27.', 'Runway designation', 'moderate', '{}'),
  ('ga-aviation', 'aprons', 'The area of an airport where aircraft are parked, loaded, unloaded and refuelled is the:', 'Clearway', 'Apron', 'Runway', 'Taxiway', 'B', 'The apron is the defined area for parking, loading/unloading, refuelling and boarding.', 'Aerodrome areas', 'easy', '{}'),
  ('ga-aviation', 'cns-navaids', 'In an Instrument Landing System (ILS), lateral (left–right) guidance is provided by the:', 'DME', 'Marker beacon', 'Localizer', 'Glide slope', 'C', 'The localizer gives lateral guidance along the runway centreline; the glide slope gives vertical guidance.', 'ILS', 'moderate', '{}'),
  ('ga-aviation', 'aviation-abbreviations', 'In aviation, VOR stands for:', 'Vertical Obstacle Reference', 'Very high Output Receiver', 'Visual Orientation Radar', 'VHF Omnidirectional Range', 'D', 'VOR = VHF Omnidirectional Range, a radio navigation aid.', 'Navigation aids', 'easy', '{}'),
  ('ga-aviation', 'aviation-meteorology', 'A METAR is:', 'A routine aerodrome weather observation report', 'A forecast for a flight route', 'A flight plan format', 'A notice to airmen about hazards', 'A', 'METAR is a routine meteorological report of current aerodrome weather. A TAF is the aerodrome forecast.', 'METAR', 'moderate', '{}'),
  ('ga-aviation', 'atc-basics', 'Transponder code 7700 indicates:', 'Unlawful interference (hijack)', 'General emergency', 'VFR flight', 'Radio communication failure', 'B', '7700 = emergency, 7600 = radio failure, 7500 = unlawful interference.', 'Emergency squawk codes', 'exam', '{}'),
  ('ga-aviation', 'atc-basics', 'Which ATC unit controls aircraft on the runway and in the immediate vicinity of the aerodrome?', 'Area Control Centre', 'Approach Control', 'Aerodrome Control (Tower)', 'Flight Information Centre', 'C', 'Aerodrome (tower) control handles runway movements and traffic close to the airport.', 'ATC units', 'moderate', '{}'),
  ('ga-aviation', 'flight-basics', 'Which force acts opposite to the weight of an aircraft in flight?', 'Thrust', 'Friction', 'Drag', 'Lift', 'D', 'The four forces are lift vs weight and thrust vs drag.', 'Forces on an aircraft', 'easy', '{}'),
  ('ga-aviation', 'flight-basics', 'An aircraft altimeter works by measuring:', 'Static air pressure', 'Air temperature', 'Radio signal delay from ground', 'Engine speed', 'A', 'A pressure altimeter converts static pressure into altitude (a radio altimeter uses radio signals).', 'Altimeter', 'moderate', '{}'),
  ('ga-aviation', 'passenger-processing', 'At customs, the Green Channel is meant for passengers who:', 'Are diplomats', 'Have nothing to declare', 'Carry dutiable goods', 'Are transit passengers', 'B', 'Green Channel = nothing to declare; Red Channel = goods to declare.', 'Customs channels', 'easy', '{}'),
  ('ga-aviation', 'security-process', 'The part of an airport beyond the security screening point is called the:', 'Kerbside', 'Landside', 'Airside', 'Forecourt', 'C', 'Airside is the controlled area beyond screening; landside is open to the public.', 'Airside and landside', 'moderate', '{}'),
  ('ga-aviation', 'terminals', 'A passenger boarding bridge connecting the terminal gate to the aircraft door is also called:', 'Apron bridge', 'Taxi link', 'Ramp', 'Aerobridge', 'D', 'It is commonly called an aerobridge or jet bridge.', 'Terminal facilities', 'easy', '{}'),
  ('ga-aviation', 'aviation-safety', 'The cockpit voice recorder and flight data recorder (''black boxes'') are usually painted:', 'Bright orange', 'Black', 'Yellow with black stripes', 'Silver', 'A', 'They are painted bright orange so they can be located easily after an accident.', 'Flight recorders', 'moderate', '{}'),
  ('ga-aviation', 'airlines-manufacturers', 'Embraer, a manufacturer of regional jets, is based in:', 'Italy', 'Brazil', 'Canada', 'France', 'B', 'Embraer is a Brazilian aerospace company.', 'Aircraft manufacturers', 'moderate', '{}'),
  ('ga-aviation', 'baggage', 'Baggage handed over at check-in and carried in the aircraft hold is called:', 'Excess baggage', 'Cabin baggage', 'Hold (checked) baggage', 'Unaccompanied baggage', 'C', 'Checked or hold baggage travels in the cargo hold; cabin baggage goes with the passenger.', 'Baggage', 'easy', '{}'),
  ('ga-aviation', 'indian-polity', 'Fundamental Duties were added to the Indian Constitution by the:', '44th Amendment', '73rd Amendment', '86th Amendment', '42nd Amendment', 'D', 'The 42nd Amendment (1976) added Part IVA (Article 51A) on Fundamental Duties.', 'Fundamental Duties', 'moderate', '{}'),
  ('ga-aviation', 'indian-polity', 'The Right to Life and Personal Liberty is guaranteed by Article:', '21', '19', '32', '14', 'A', 'Article 21 protects life and personal liberty.', 'Fundamental Rights', 'easy', '{}'),
  ('ga-aviation', 'indian-geography', 'The Tropic of Cancer passes through how many Indian states?', '7', '8', '6', '9', 'B', 'Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura and Mizoram — 8 states.', 'Tropic of Cancer', 'moderate', '{}'),
  ('ga-aviation', 'general-science', 'Deficiency of Vitamin C causes:', 'Night blindness', 'Beriberi', 'Scurvy', 'Rickets', 'C', 'Scurvy — Vitamin C; rickets — D; night blindness — A; beriberi — B1.', 'Vitamins', 'easy', '{}'),
  ('ga-aviation', 'indian-economy', 'The Reserve Bank of India was established in:', '1969', '1947', '1949', '1935', 'D', 'RBI began operations on 1 April 1935; it was nationalised in 1949.', 'RBI', 'moderate', '{}'),
  ('ga-aviation', 'indian-history', 'The First Battle of Panipat (1526) was fought between Babur and:', 'Ibrahim Lodi', 'Sher Shah Suri', 'Rana Sanga', 'Hemu', 'A', 'Babur defeated Ibrahim Lodi, founding the Mughal Empire.', 'Medieval India', 'moderate', '{}'),
  ('ga-aviation', 'government-schemes', 'Pradhan Mantri Jan Dhan Yojana (2014) primarily aims at:', 'Skill development', 'Financial inclusion through bank accounts', 'Crop insurance', 'Rural housing', 'B', 'PMJDY aims to give every household access to a basic bank account.', 'Government schemes', 'easy', '{}'),
  ('physics', 'units-measurements', 'The dimensional formula of force is:', '[MLT⁻¹]', '[ML²T⁻²]', '[MLT⁻²]', '[ML⁻¹T⁻²]', 'C', 'F = ma → [M][LT⁻²] = [MLT⁻²].', 'Dimensions', 'easy', '{}'),
  ('physics', 'units-measurements', 'Which of the following is NOT a unit of energy?', 'Electron volt', 'Kilowatt-hour', 'Joule', 'Watt', 'D', 'Watt is the unit of power (J/s).', 'Units', 'easy', '{}'),
  ('physics', 'motion', 'A body starts from rest with an acceleration of 2 m/s². The distance covered in 5 s is:', '25 m', '50 m', '20 m', '10 m', 'A', 's = ut + ½at² = 0 + ½ × 2 × 25 = 25 m.', 'Equations of motion', 'easy', '{}'),
  ('physics', 'motion', 'For a given launch speed, the horizontal range of a projectile is maximum at an angle of:', '30°', '45°', '90°', '60°', 'B', 'R = u² sin 2θ / g is maximum when sin 2θ = 1, i.e. θ = 45°.', 'Projectile motion', 'easy', '{}'),
  ('physics', 'laws-of-motion', 'A force of 10 N acts for 0.5 s on a 2 kg body at rest. Its final velocity is:', '10 m/s', '1 m/s', '2.5 m/s', '5 m/s', 'C', 'Impulse = FΔt = 5 N s = mv, so v = 5/2 = 2.5 m/s.', 'Impulse–momentum', 'moderate', '{}'),
  ('physics', 'laws-of-motion', 'Rocket propulsion is based on:', 'Conservation of energy alone', 'Newton''s first law', 'Pascal''s law', 'Conservation of linear momentum', 'D', 'Exhaust gases gain backward momentum; the rocket gains equal forward momentum.', 'Conservation of momentum', 'easy', '{}'),
  ('physics', 'work-energy-power', 'If the speed of a body is doubled, its kinetic energy becomes:', '4 times', '8 times', '2 times', 'half', 'A', 'KE = ½mv² ∝ v², so doubling v gives 4 × KE.', 'Kinetic energy', 'easy', '{}'),
  ('physics', 'work-energy-power', 'A 50 kg load is lifted through 10 m in 5 s. The power required is (g = 10 m/s²):', '500 W', '1000 W', '100 W', '2500 W', 'B', 'P = mgh/t = 50 × 10 × 10 / 5 = 1000 W.', 'Power', 'moderate', '{}'),
  ('physics', 'rotational-motion', 'The moment of inertia of a thin ring of mass M and radius R about an axis through its centre, perpendicular to its plane, is:', '½MR²', '⅖MR²', 'MR²', '⅔MR²', 'C', 'All the mass is at distance R, so I = MR².', 'Moment of inertia', 'moderate', '{}'),
  ('physics', 'rotational-motion', 'A spinning skater pulls her arms in. Her angular velocity:', 'Decreases', 'Becomes zero', 'Stays the same', 'Increases', 'D', 'Angular momentum Iω is conserved; I decreases, so ω increases.', 'Conservation of angular momentum', 'moderate', '{}'),
  ('physics', 'system-of-particles', 'Two particles of masses 2 kg and 3 kg are at x = 0 and x = 5 m. The centre of mass is at:', 'x = 3 m', 'x = 3.5 m', 'x = 2 m', 'x = 2.5 m', 'A', 'x_cm = (2×0 + 3×5)/5 = 3 m.', 'Centre of mass', 'moderate', '{}'),
  ('physics', 'gravitation', 'At a height equal to the Earth''s radius R above the surface, the acceleration due to gravity is:', 'g/2', 'g/4', 'g/9', '2g', 'B', 'g'' = g R²/(2R)² = g/4.', 'Variation of g with height', 'exam', '{}'),
  ('physics', 'gravitation', 'The escape velocity from the Earth''s surface is about:', '3.1 km/s', '7.9 km/s', '11.2 km/s', '9.8 km/s', 'C', 'v_e = √(2gR) ≈ 11.2 km/s. 7.9 km/s is the orbital speed near the surface.', 'Escape velocity', 'easy', '{}'),
  ('physics', 'properties-of-matter', 'Bernoulli''s theorem for fluid flow is a statement of the conservation of:', 'Mass', 'Momentum', 'Charge', 'Energy', 'D', 'Pressure energy + kinetic energy + potential energy per unit volume stays constant along a streamline.', 'Bernoulli''s principle', 'moderate', '{}'),
  ('physics', 'properties-of-matter', 'The gauge pressure at a depth of 10 m in water is (ρ = 1000 kg/m³, g = 10 m/s²):', '10⁵ Pa', '10⁶ Pa', '10³ Pa', '10⁴ Pa', 'A', 'P = ρgh = 1000 × 10 × 10 = 10⁵ Pa.', 'Hydrostatic pressure', 'moderate', '{}'),
  ('physics', 'properties-of-matter', 'Young''s modulus of a perfectly rigid body is:', '1', 'Infinite', 'Equal to its bulk modulus', 'Zero', 'B', 'A perfectly rigid body has zero strain for any stress, so Y = stress/strain is infinite.', 'Elasticity', 'exam', '{}'),
  ('physics', 'thermodynamics', 'For an ideal gas in an isothermal process:', 'ΔP = 0', 'W = 0', 'ΔU = 0', 'Q = 0', 'C', 'Internal energy of an ideal gas depends only on temperature, which is constant.', 'Isothermal process', 'moderate', '{}'),
  ('physics', 'thermodynamics', 'A Carnot engine works between 500 K and 300 K. Its efficiency is:', '60%', '30%', '25%', '40%', 'D', 'η = 1 − T₂/T₁ = 1 − 300/500 = 0.4 = 40%.', 'Carnot efficiency', 'exam', '{}'),
  ('physics', 'kinetic-theory', 'If the absolute temperature of a gas is made 4 times, the rms speed of its molecules:', 'Doubles', 'Is unchanged', 'Becomes 4 times', 'Halves', 'A', 'v_rms = √(3RT/M) ∝ √T; √4 = 2.', 'RMS speed', 'moderate', '{}'),
  ('physics', 'oscillations', 'If the length of a simple pendulum is made four times, its time period:', 'Is unchanged', 'Doubles', 'Becomes four times', 'Halves', 'B', 'T = 2π√(l/g) ∝ √l; √4 = 2.', 'Simple pendulum', 'easy', '{}'),
  ('physics', 'waves', 'A sound wave of frequency 170 Hz travels at 340 m/s. Its wavelength is:', '4 m', '1 m', '2 m', '0.5 m', 'C', 'λ = v/f = 340/170 = 2 m.', 'Wave equation', 'easy', '{}'),
  ('physics', 'electrostatics', 'If the distance between two point charges is doubled, the force between them becomes:', '2F', 'F/2', '4F', 'F/4', 'D', 'Coulomb''s law: F ∝ 1/r², so doubling r gives F/4.', 'Coulomb''s law', 'easy', '{}'),
  ('physics', 'electrostatics', 'Two capacitors of 6 μF each are connected in series. The equivalent capacitance is:', '3 μF', '1.5 μF', '6 μF', '12 μF', 'A', '1/C = 1/6 + 1/6 = 1/3, so C = 3 μF.', 'Capacitors in series', 'moderate', '{}'),
  ('physics', 'electrostatics', 'The total electric flux through a closed surface enclosing a charge q is:', 'Zero', 'q/ε₀', 'qε₀', 'q/4πε₀', 'B', 'Gauss''s law: Φ = q_enclosed/ε₀.', 'Gauss''s law', 'moderate', '{}'),
  ('physics', 'current-electricity', 'Resistors of 4 Ω and 12 Ω are connected in parallel. The equivalent resistance is:', '16 Ω', '8 Ω', '3 Ω', '2 Ω', 'C', 'R = (4 × 12)/(4 + 12) = 48/16 = 3 Ω.', 'Parallel resistors', 'easy', '{}'),
  ('physics', 'current-electricity', 'The resistance of a 220 V, 100 W bulb is:', '440 Ω', '2.2 Ω', '48.4 Ω', '484 Ω', 'D', 'R = V²/P = 220²/100 = 484 Ω.', 'Electric power', 'moderate', '{}'),
  ('physics', 'moving-charges-magnetism', 'The magnetic field at the centre of a circular loop of radius R carrying current I is:', 'μ₀I/2R', 'μ₀I/4R', 'μ₀I/2πR', 'μ₀IR/2', 'A', 'From the Biot–Savart law, B = μ₀I/2R at the centre.', 'Biot–Savart law', 'moderate', '{}'),
  ('physics', 'moving-charges-magnetism', 'The magnetic force on a charge moving parallel to a magnetic field is:', 'qv/B', 'Zero', 'Maximum', 'qvB', 'B', 'F = qvB sin θ, and θ = 0° gives F = 0.', 'Lorentz force', 'easy', '{}'),
  ('physics', 'magnetism', 'A substance with a small negative magnetic susceptibility is:', 'Ferrimagnetic', 'Ferromagnetic', 'Diamagnetic', 'Paramagnetic', 'C', 'Diamagnetic materials are weakly repelled, with small negative susceptibility.', 'Magnetic materials', 'moderate', '{}'),
  ('physics', 'emi', 'Lenz''s law is a consequence of the conservation of:', 'Momentum', 'Mass', 'Charge', 'Energy', 'D', 'The induced current opposes the change causing it; otherwise energy would be created from nothing.', 'Lenz''s law', 'moderate', '{}'),
  ('physics', 'alternating-current', 'At resonance in a series LCR circuit, the power factor is:', '1', '0.5', '0', '0.707', 'A', 'At resonance X_L = X_C, so Z = R and cos φ = R/Z = 1.', 'LCR resonance', 'exam', '{}'),
  ('physics', 'alternating-current', 'A transformer works on the principle of:', 'Electrostatic induction', 'Mutual induction', 'Self-induction', 'Eddy currents', 'B', 'A changing current in the primary induces an emf in the secondary through mutual induction.', 'Transformer', 'easy', '{}'),
  ('physics', 'em-waves', 'Which of these electromagnetic waves has the longest wavelength?', 'Microwaves', 'X-rays', 'Radio waves', 'Infrared', 'C', 'Radio waves have the longest wavelength in the EM spectrum.', 'EM spectrum', 'easy', '{}'),
  ('physics', 'ray-optics', 'An object is placed 30 cm in front of a concave mirror of focal length 15 cm. The image is formed:', '15 cm in front of the mirror', '30 cm behind the mirror', 'At infinity', '30 cm in front of the mirror', 'D', '1/v = 1/f − 1/u = −1/15 + 1/30 = −1/30, so v = −30 cm: real, inverted, same size, at C.', 'Mirror formula', 'exam', '{}'),
  ('physics', 'ray-optics', 'The power of a convex lens of focal length 25 cm is:', '+4 D', '+25 D', '+0.25 D', '−4 D', 'A', 'P = 1/f (in metres) = 1/0.25 = +4 D.', 'Power of a lens', 'easy', '{}'),
  ('physics', 'ray-optics', 'The speed of light in glass of refractive index 1.5 is (c = 3 × 10⁸ m/s):', '1.5 × 10⁸ m/s', '2 × 10⁸ m/s', '3 × 10⁸ m/s', '4.5 × 10⁸ m/s', 'B', 'v = c/n = 3 × 10⁸ / 1.5 = 2 × 10⁸ m/s.', 'Refractive index', 'moderate', '{}'),
  ('physics', 'wave-optics', 'In Young''s double-slit experiment, λ = 600 nm, slit separation 0.5 mm and screen distance 1 m. The fringe width is:', '0.3 mm', '2.4 mm', '1.2 mm', '0.6 mm', 'C', 'β = λD/d = (600 × 10⁻⁹ × 1)/(0.5 × 10⁻³) = 1.2 × 10⁻³ m.', 'Fringe width', 'exam', '{}'),
  ('physics', 'dual-nature', 'In the photoelectric effect, the maximum kinetic energy of emitted electrons depends on:', 'Area of the plate', 'Intensity of light', 'Time of exposure', 'Frequency of light', 'D', 'K_max = hν − φ; intensity changes the number of electrons, not their maximum energy.', 'Photoelectric effect', 'moderate', '{}'),
  ('physics', 'dual-nature', 'The de Broglie wavelength of an electron accelerated through 100 V is approximately:', '0.123 nm', '0.0123 nm', '12.3 nm', '1.23 nm', 'A', 'λ = 1.227/√V nm = 1.227/10 ≈ 0.123 nm.', 'de Broglie wavelength', 'challenging', '{}'),
  ('physics', 'atoms', 'The energy of the electron in the n = 2 orbit of a hydrogen atom is:', '−13.6 eV', '−3.4 eV', '−6.8 eV', '−1.51 eV', 'B', 'Eₙ = −13.6/n² eV = −13.6/4 = −3.4 eV.', 'Bohr model', 'moderate', '{}'),
  ('physics', 'nuclei', 'A radioactive sample has a half-life of 10 days. The fraction remaining after 30 days is:', '1/6', '1/4', '1/8', '1/3', 'C', '30 days = 3 half-lives, so (1/2)³ = 1/8 remains.', 'Half-life', 'moderate', '{}'),
  ('physics', 'semiconductors', 'Which logic gate gives a LOW output only when all its inputs are HIGH?', 'OR', 'NOR', 'AND', 'NAND', 'D', 'NAND = NOT(AND): the output is 0 only when every input is 1.', 'Logic gates', 'moderate', '{}'),
  ('physics', 'semiconductors', 'Which dopant added to silicon produces an n-type semiconductor?', 'Phosphorus', 'Gallium', 'Aluminium', 'Boron', 'A', 'Phosphorus is pentavalent and donates free electrons. Boron, aluminium and gallium give p-type.', 'Doping', 'easy', '{}'),
  ('physics', 'semiconductors', 'In a forward-biased p–n junction diode, the width of the depletion layer:', 'Stays the same', 'Decreases', 'Becomes infinite', 'Increases', 'B', 'Forward bias opposes the barrier potential, narrowing the depletion region.', 'p–n junction', 'exam', '{}'),
  ('mathematics', 'sets', 'If n(A) = 20, n(B) = 15 and n(A ∩ B) = 5, then n(A ∪ B) is:', '35', '25', '30', '40', 'C', 'n(A ∪ B) = 20 + 15 − 5 = 30.', 'Union of sets', 'easy', '{}'),
  ('mathematics', 'relations', 'The number of relations from a set with 2 elements to a set with 3 elements is:', '6', '32', '8', '64', 'D', 'A × B has 6 elements; relations are its subsets: 2⁶ = 64.', 'Number of relations', 'moderate', '{}'),
  ('mathematics', 'functions', 'If f(x) = 2x + 3, then f⁻¹(x) is:', '(x − 3)/2', '2x − 3', '(x + 3)/2', '(x − 2)/3', 'A', 'y = 2x + 3 ⇒ x = (y − 3)/2.', 'Inverse function', 'easy', '{}'),
  ('mathematics', 'trigonometry', 'The value of sin 75° is:', '(√6 − √2)/4', '(√6 + √2)/4', '√3/2', '(√3 + 1)/2', 'B', 'sin(45° + 30°) = sin45 cos30 + cos45 sin30 = (√6 + √2)/4.', 'Compound angles', 'moderate', '{}'),
  ('mathematics', 'trigonometry', 'The maximum value of 3 sin x + 4 cos x is:', '4', '7', '5', '3', 'C', 'Maximum of a sin x + b cos x is √(a² + b²) = 5.', 'Range of trig expressions', 'exam', '{}'),
  ('mathematics', 'inverse-trigonometry', 'tan⁻¹(1) + tan⁻¹(1/√3) equals:', 'π/3', 'π/2', '7π/12', '5π/12', 'D', 'π/4 + π/6 = 5π/12.', 'Principal values', 'moderate', '{}'),
  ('mathematics', 'inverse-trigonometry', 'For x in [−1, 1], sin⁻¹x + cos⁻¹x equals:', 'π/2', 'π/4', 'π', '0', 'A', 'This is a standard identity: sin⁻¹x + cos⁻¹x = π/2.', 'Inverse trig identities', 'easy', '{}'),
  ('mathematics', 'complex-numbers', 'The value of i²⁰²⁶ is:', '1', '−1', 'i', '−i', 'B', '2026 = 4 × 506 + 2, so i²⁰²⁶ = i² = −1.', 'Powers of i', 'moderate', '{}'),
  ('mathematics', 'complex-numbers', 'The modulus of 3 + 4i is:', '7', '25', '5', '√7', 'C', '|3 + 4i| = √(9 + 16) = 5.', 'Modulus', 'easy', '{}'),
  ('mathematics', 'quadratic-equations', 'If α and β are the roots of x² − 5x + 6 = 0, then α² + β² is:', '25', '19', '12', '13', 'D', 'α + β = 5, αβ = 6; α² + β² = 25 − 12 = 13.', 'Sum and product of roots', 'moderate', '{}'),
  ('mathematics', 'permutations-combinations', 'The value of ⁸C₃ is:', '56', '70', '336', '24', 'A', '⁸C₃ = (8 × 7 × 6)/(3 × 2 × 1) = 56.', 'Combinations', 'easy', '{}'),
  ('mathematics', 'binomial-theorem', 'The number of terms in the expansion of (x + y)¹⁰ is:', '10', '11', '12', '20', 'B', '(x + y)ⁿ has n + 1 terms.', 'Binomial expansion', 'easy', '{}'),
  ('mathematics', 'binomial-theorem', 'The coefficient of the middle term in the expansion of (1 + x)⁶ is:', '35', '6', '20', '15', 'C', 'The middle term is T₄ = ⁶C₃ x³, coefficient 20.', 'Middle term', 'moderate', '{}'),
  ('mathematics', 'sequences-series', 'In an AP, the 3rd term is 8 and the 7th term is 20. The 10th term is:', '32', '26', '30', '29', 'D', '4d = 12 ⇒ d = 3, a = 2; a₁₀ = 2 + 27 = 29.', 'Arithmetic progression', 'moderate', '{}'),
  ('mathematics', 'sequences-series', 'The sum of the infinite GP 1 + 1/2 + 1/4 + … is:', '2', 'Infinite', '1', '3/2', 'A', 'S∞ = a/(1 − r) = 1/(1 − ½) = 2.', 'Infinite GP', 'easy', '{}'),
  ('mathematics', 'straight-lines', 'The slope of the line through (2, 3) and (4, 7) is:', '1/2', '2', '4', '−2', 'B', 'm = (7 − 3)/(4 − 2) = 2.', 'Slope', 'easy', '{}'),
  ('mathematics', 'straight-lines', 'The perpendicular distance of (3, 4) from the line 3x + 4y − 5 = 0 is:', '3', '5', '4', '20', 'C', '|9 + 16 − 5|/√(9 + 16) = 20/5 = 4.', 'Distance of a point from a line', 'moderate', '{}'),
  ('mathematics', 'circles', 'The centre and radius of x² + y² − 4x + 6y − 12 = 0 are:', '(−2, 3), 5', '(2, −3), 25', '(2, 3), 5', '(2, −3), 5', 'D', 'Centre (−g, −f) = (2, −3); r = √(4 + 9 + 12) = 5.', 'Equation of a circle', 'moderate', '{}'),
  ('mathematics', 'conic-sections', 'The focus of the parabola y² = 8x is:', '(2, 0)', '(8, 0)', '(4, 0)', '(0, 2)', 'A', 'y² = 4ax with a = 2 gives focus (a, 0) = (2, 0).', 'Parabola', 'easy', '{}'),
  ('mathematics', 'conic-sections', 'The eccentricity of the ellipse x²/25 + y²/16 = 1 is:', '5/3', '3/5', '4/5', '9/25', 'B', 'e = √(1 − b²/a²) = √(1 − 16/25) = 3/5.', 'Ellipse', 'exam', '{}'),
  ('mathematics', 'limits', 'lim (x → 0) sin 3x / x equals:', '0', '1/3', '3', '1', 'C', 'sin 3x / x = 3 · (sin 3x / 3x) → 3.', 'Standard limits', 'easy', '{}'),
  ('mathematics', 'limits', 'lim (x → 2) (x² − 4)/(x − 2) equals:', '0', 'Does not exist', '2', '4', 'D', 'Factor: (x − 2)(x + 2)/(x − 2) = x + 2 → 4.', 'Limits by factorisation', 'easy', '{}'),
  ('mathematics', 'continuity', 'The function f(x) = |x| at x = 0 is:', 'Continuous but not differentiable', 'Differentiable but not continuous', 'Continuous and differentiable', 'Discontinuous', 'A', '|x| is continuous at 0, but the left derivative (−1) differs from the right derivative (+1).', 'Continuity and differentiability', 'moderate', '{}'),
  ('mathematics', 'differentiation', 'd/dx (x² sin x) is:', '2x cos x', '2x sin x + x² cos x', '2x sin x − x² cos x', 'x² cos x', 'B', 'Product rule: (x²)′ sin x + x² (sin x)′.', 'Product rule', 'moderate', '{}'),
  ('mathematics', 'differentiation', 'd/dx (tan⁻¹ x) is:', 'sec² x', '−1/(1 + x²)', '1/(1 + x²)', '1/√(1 − x²)', 'C', 'Standard derivative.', 'Derivatives of inverse trig', 'easy', '{}'),
  ('mathematics', 'applications-derivatives', 'The minimum value of x² − 6x + 10 is:', '3', '10', '−1', '1', 'D', 'x² − 6x + 10 = (x − 3)² + 1, minimum 1 at x = 3.', 'Maxima and minima', 'moderate', '{}'),
  ('mathematics', 'applications-derivatives', 'The slope of the tangent to y = x³ at x = 2 is:', '12', '8', '4', '6', 'A', 'dy/dx = 3x² = 12 at x = 2.', 'Tangents', 'easy', '{}'),
  ('mathematics', 'indefinite-integration', '∫ x eˣ dx equals:', 'eˣ(x + 1) + C', 'eˣ(x − 1) + C', 'x² eˣ/2 + C', 'x eˣ + C', 'B', 'By parts: x eˣ − ∫ eˣ dx = eˣ(x − 1) + C.', 'Integration by parts', 'moderate', '{}'),
  ('mathematics', 'definite-integration', '∫₀^{π/2} sin² x dx equals:', '1/2', '1', 'π/4', 'π/2', 'C', 'Using ∫₀^a f(x) dx = ∫₀^a f(a − x) dx, the sin² and cos² integrals are equal and sum to π/2, so each is π/4.', 'Properties of definite integrals', 'exam', '{}'),
  ('mathematics', 'definite-integration', '∫₋₁¹ x³ dx equals:', '1', '1/2', '2', '0', 'D', 'x³ is an odd function, so its integral over a symmetric interval is 0.', 'Odd functions', 'easy', '{}'),
